import csv
from collections import defaultdict
p='/archive/payment_batch_export_VSgBeCMTtx.tsv'
rows=[]
with open(p,newline='') as f:
    r=csv.DictReader(f,delimiter='\t')
    for row in r:
        rows.append(row)

# group by device and payment method with distinct customers
for key,col in [('device','device_fingerprint'),('pm','payment_method_fingerprint')]:
    g=defaultdict(set)
    ids=defaultdict(list)
    for row in rows:
        g[row[col]].add(row['customer_ref'])
        ids[row[col]].append(row['row_id'])
    print('---',key,'shared_across_customers---')
    for fp,custs in sorted(g.items()):
        if len(custs)>=2:
            print(fp,len(custs),sorted(custs),ids[fp])

# per-customer count and store spread
print('---customer_summary---')
cust_rows=defaultdict(list)
for row in rows:
    cust_rows[row['customer_ref']].append(row)
for c,rs in sorted(cust_rows.items(), key=lambda kv: len(kv[1]), reverse=True)[:10]:
    stores={x['store_ref'] for x in rs}
    devs={x['device_fingerprint'] for x in rs}
    pms={x['payment_method_fingerprint'] for x in rs}
    print(c,'n=',len(rs),'stores=',len(stores),'devs=',len(devs),'pms=',len(pms))
